          desc: R`[[move]] بينقل ملف أو فولدر لمكان تاني، و [[ren]] (أو [[rename]]) بيغيّر الاسم في نفس المكان. في bash الاتنين [[mv]]. الشكل: القديم الأول وبعده الجديد. و [[move *.log logs\]] بينقل كل ملفات .log لفولدر logs، والـ [[\]] في الآخر بتوضح إنه فولدر.

[[ren]] بياخد الاسم الجديد لوحده من غير مسار: [[ren src\old.js new.js]] صح، و [[ren old.js src\new.js]] غلط. وبيقبل wildcards بطريقة خاصة: [[ren *.txt *.md]] بيغيّر امتداد كل ملفات txt لـ md في أمر واحد، والنجمة في الجديد معناها «سيب الاسم زي ما هو».

[[move]] بيسأل قبل ما يكتب فوق ملف موجود لما تكتبه بإيدك، وجوه ملف bat بيكتب فوقه من غير سؤال؛ [[/-Y]] بتخليه يسأل دايمًا. وتغيير أسامي بترقيم (photo_001 و photo_002) محتاج لوب، ده درس rename-files.bat.`,
