      n: R`ملفات .bat: هتقابلها في مشاريع قديمة وأدوات ويندوز، وهي أسهل زرار دبل كليك. ابدأ بأول درس، وكل ملف بعده بيتحفظ ويتشغّل بنفس الطريقة`,
