            "لو فاضي، اسأل اليوزر يكتبه ([[set /p]] زي read). علامات التنصيص بتحافظ على المسافة اللي بعد [[:]].",
            "حسبة رقمية ([[/a]]).",
            "اطبع المتغيرين.",
